    ["Status Bar Text"] = "Statusleistentext",
    ["Always display the text on XP, health, mana, rage, energy, or happiness status bars."] = "Zeigt immer den Text auf den Leisten für EP, Gesundheit, Mana, Wut, Energie oder Zufriedenheit an.",
    ["Show Target of Target"] = "Ziel des Ziels anzeigen",
    ["Toggles the display of the target of your target."] = "Schaltet die Anzeige des Ziels Eures Ziels ein oder aus.",
