    ["Always Show ActionBars"] = "Toujours afficher les barres d'action",
    ["Check this option to always display extra actionbars."] = "Cochez cette option pour toujours afficher les barres d'action supplémentaires.",
    ["Lock ActionBars"] = "Verrouiller les barres d'action",
