    { "^Zone: (.-)$", { "zone" }, "Zona: {zone}" },
    { "^Rank (.-)$", { "n" }, "Grau {n}" },
    { "^New: (.-)$", { "spell" }, "Novo: {spell}" },
    { "^RANK (.-)$", { "n" }, "GRAU {n}" },
    { "^Spec (.-)$", { "n" }, "Espec. {n}" },
    { "^from (.-)$", { "heroic" }, "a partir de {heroic}" },
    { "^(.-) of (.-)$", { "n", "total" }, "{n} de {total}" },
    { "^Buy (.-)$", { "cost" }, "Comprar por {cost}" },
    { "^(.-) new$", { "n" }, "{n} novas" },
    { "^(.-) yd$", { "n" }, "{n} m" },
    { "^of (.-)$", { "total" }, "de {total}" },
  },
}
